<?php declare(strict_types=1); use App\Core\Csrf; $edit=is_array($campaign);$value=static fn(string $k,mixed $d='')=>$edit?($campaign[$k]??$d):$d;ob_start(); ?><section class="admin-page-head"><div><p class="admin-eyebrow">Rascunho com snapshot</p><h2><?= $edit?'Editar campanha':'Nova campanha' ?></h2><p>O template selecionado e o conteúdo são congelados ao criar/agendar a campanha.</p></div></section><section class="admin-panel"><form class="admin-form-grid" method="post" action="<?= $edit?'/admin/campanhas/'.(int)$campaign['id']:'/admin/campanhas' ?>"><input type="hidden" name="_token" value="<?= e(Csrf::token()) ?>"><label>Nome interno<input required maxlength="180" name="name" value="<?= e((string)$value('name')) ?>"></label><label>Template marketing<select required name="template_id"><?php foreach($templates as $t): ?><option value="<?= (int)$t['id'] ?>"<?= (int)$value('template_id')===(int)$t['id']?' selected':'' ?>>v<?= (int)$t['version'] ?> · <?= e((string)$t['subject_template']) ?></option><?php endforeach; ?></select></label><label>Título enviado<input required maxlength="255" name="title" value="<?= e((string)$value('title')) ?>"></label><label>Conteúdo<textarea required maxlength="4000" name="body"><?= e((string)$value('body')) ?></textarea></label><label>Segmento<select name="segment"><option value="active"<?= $value('segment','active')==='active'?' selected':'' ?>>Usuários ativos com opt-in</option><option value="plan"<?= $value('segment')==='plan'?' selected':'' ?>>Plano específico</option><option value="new"<?= $value('segment')==='new'?' selected':'' ?>>Novos usuários com opt-in</option></select></label><label>ID do plano (somente segmento plano)<input name="plan_id" value="<?= e((string)$value('plan_id')) ?>"></label><button class="admin-button">Salvar rascunho</button></form><?php if($edit&&$campaign['status']==='draft'): ?><form method="post" action="/admin/campanhas/<?= (int)$campaign['id'] ?>/agendar"><input type="hidden" name="_token" value="<?= e(Csrf::token()) ?>"><label>Agendar<input type="datetime-local" required name="scheduled_at"></label><button class="admin-button">Agendar enfileiramento</button></form><?php endif; ?></section><?php $content=(string)ob_get_clean();require __DIR__.'/../layouts/admin.php';
